    var(--_g2) calc(1*var(--s)) calc(2*var(--s)),
    var(--_g2) calc(2*var(--s)) 0,
    var(--_g2) calc(3*var(--s)) calc(3*var(--s)),
    var(--_g2) calc(4*var(--s)) calc(1*var(--s)),
    #604848; /* color 2 */
  background-size: calc(5*var(--s)) calc(5*var(--s));
