/* ---------- the studio: softboxes and strip lights (seen in reflections), a graded backdrop, the key and rim lights ---------- */
function makeStudioEnv() {
  const env = new THREE.Scene();
  env.add(new THREE.Mesh(new THREE.SphereGeometry(100, 32, 16), new THREE.ShaderMaterial({ side: THREE.BackSide,
    vertexShader: 'varying vec3 vD; void main(){ vD = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
    fragmentShader: 'varying vec3 vD; void main(){ float y = vD.y; vec3 c = mix(vec3(0.020, 0.022, 0.026), vec3(0.055, 0.060, 0.068), smoothstep(-0.2, 0.15, y)); c = mix(c, vec3(0.012, 0.013, 0.015), smoothstep(0.2, 0.9, y)); gl_FragColor = vec4(c, 1.0); }' })));
  const panel = (w, h, pos, I, tint = [1, 1, 1]) => { const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color: new THREE.Color(I * tint[0], I * tint[1], I * tint[2]), side: THREE.DoubleSide }));
    m.position.set(...pos); m.lookAt(0, 8, 0); env.add(m); };
  panel(46, 34, [-42, 48, 38], 5.0);                  // key softbox, high front left
  panel(8, 70, [55, 18, -32], 7.0, [0.92, 0.96, 1.0]);  // strip light, back right (the long highlight on the metal)
  panel(8, 60, [-58, 14, -26], 4.0, [1.0, 0.97, 0.92]); // strip light, back left
  panel(36, 36, [0, 75, 0], 1.6);                     // overhead
  panel(60, 20, [20, 6, 60], 0.35);                   // low front fill (bounce)
  const pm = new THREE.PMREMGenerator(renderer); const t = pm.fromScene(env, 0.02).texture; pm.dispose(); return t;
}
scene.environment = makeStudioEnv();
const KEY = new THREE.DirectionalLight(0xfff6ec, 1.9); KEY.position.set(-0.62, 0.72, 0.6); scene.add(KEY);   // (directional lights live in
const RIM = new THREE.DirectionalLight(0xdce8ff, 2.6); RIM.position.set(0.85, 0.25, -0.75); scene.add(RIM);    //  `scene`: with the floating
const RIM2 = new THREE.DirectionalLight(0xfff0e0, 1.3); RIM2.position.set(-0.9, 0.18, -0.6); scene.add(RIM2);  //  origin only direction matters)

// the backdrop around the whole set, and the floor that melts into it; a soft contact shadow under the product
const BACKDROP = new THREE.Mesh(new THREE.SphereGeometry(800, 48, 24), new THREE.ShaderMaterial({ side: THREE.BackSide, depthWrite: false,
  vertexShader: 'varying vec3 vD; void main(){ vD = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
  fragmentShader: 'varying vec3 vD; void main(){ float y = vD.y; vec3 c = mix(vec3(0.036, 0.040, 0.047), vec3(0.012, 0.013, 0.016), smoothstep(0.0, 0.6, y)); gl_FragColor = vec4(c, 1.0); }' }));
BACKDROP.renderOrder = -2; universe.add(BACKDROP);
// the floor: unlit (lights would give it a hard bright half), a soft pool of light under the product that fades into the backdrop's
// own colour at the edge (no horizon line), and a contact shadow — a wide soft falloff and a tight dark core under the base
const FLOOR = new THREE.Mesh(new THREE.CircleGeometry(160, 128).rotateX(-Math.PI / 2), new THREE.ShaderMaterial({ transparent: true, depthWrite: true,
  vertexShader: 'varying vec2 vP; void main(){ vP = position.xz; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
  fragmentShader: `varying vec2 vP;
    void main(){ float d = length(vP);
      vec3 col = mix(vec3(0.060, 0.064, 0.072), vec3(0.030, 0.034, 0.040), smoothstep(8.0, 70.0, d));     // the pool of light → the backdrop colour
      float sh = 0.55 * exp(-pow(max(d - 5.2, 0.0) / 5.0, 2.0)) + 0.35 * exp(-pow(max(d - 5.8, 0.0) / 0.9, 2.0));   // contact shadow
      col *= 1.0 - clamp(sh, 0.0, 0.9) * step(d, 20.0);
      gl_FragColor = vec4(col, 1.0 - smoothstep(110.0, 160.0, d)); }` }));
universe.add(FLOOR);

/* ---------- a generic "object" point cloud: physical size where resolved, never below a minimum pixel size ---------- */
// attributes: position (cloud units), aSize (physical radius, cloud units), aBright (0..n), aCol (rgb)
function makeCloud({ positions, sizes, brights, colors, unitKm, minPx = 1.2, maxPx = 40, gain = 1, order = 4, shape = 'soft', shapes = null }) {
  const g = new THREE.Group(); g.matrixAutoUpdate = false; g.matrix.makeScale(unitKm, unitKm, unitKm);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  geo.setAttribute('aBright', new THREE.BufferAttribute(brights, 1));
  geo.setAttribute('aCol', new THREE.BufferAttribute(colors, 3));
  geo.setAttribute('aShape', new THREE.BufferAttribute(shapes || new Float32Array(sizes.length * 3).fill(1), 3));
  const U = { uPxPerRad: PXR_U, uDpr: DPR_U, uFade: { value: 1 }, uMaxPx: { value: maxPx }, uMinPx: { value: minPx }, uGain: { value: gain },
    uCamU: { value: new THREE.Vector3() }, uFocus: { value: new THREE.Vector3() }, uFocusR: { value: 1e30 }, uUnitPx: { value: 1 } };
  const mat = new THREE.ShaderMaterial({
    uniforms: U,
    vertexShader: `
      attribute float aSize; attribute float aBright; attribute vec3 aCol; attribute vec3 aShape; varying vec3 vShape; uniform float uMinPx; uniform float uGain; uniform vec3 uCamU;
      uniform vec3 uFocus; uniform float uFocusR;
      varying vec3 vCol; varying float vA; varying float vSig;
      ${POINT_COMMON}${SIG_GLSL}
      void main() {
        vec4 mv0 = modelViewMatrix * vec4(position, 1.0);
        float d = max(distance(position, uCamU), 1e-9);
        float physPx = aSize / d * uPxPerRad;                        // true radius in pixels
        float px = clamp(max(physPx, uMinPx), 0.0, uMaxPx);
        // light is conserved when a resolved object shrinks below the minimum size: dim instead of shrinking
        float cover = clamp(physPx / uMinPx, 0.0, 1.0);
        float foc = exp(-pow(distance(position, uFocus) / uFocusR, 2.0));   // depth window around the camera's subject
        vA = uFade * uGain * aBright * mix(cover, 1.0, 0.35) * foc;
        vCol = aCol; vShape = aShape;
        gl_Position = projectionMatrix * farPush(mv0);
        float sz = max(px * 2.0 * uDpr, 3.2); vA *= min(1.0, px * 2.0 * uDpr / 3.2);
        gl_PointSize = vA < 0.002 ? 0.0 : sz; vSig = spriteSigma(sz); vA *= pow(0.19 / vSig, 1.3);
      }`,
    fragmentShader: shape === 'disc' ? `
      varying vec3 vCol; varying float vA; varying float vSig;
      void main() { vec2 d = gl_PointCoord * 2.0 - 1.0; float r2 = dot(d, d); if (r2 > 1.0) discard;
        float e = exp(-r2 * 3.2); gl_FragColor = vec4(vCol * e * vA, 1.0); }` : shape === 'galaxy' ? `
      varying vec3 vCol; varying float vA; varying float vSig; varying vec3 vShape;
      void main() {                                   // an inclined disc with a warm bulge; tiny ones stay a soft blob
        vec2 d = gl_PointCoord * 2.0 - 1.0; float c = cos(vShape.y), s = sin(vShape.y);
        vec2 e = mat2(c, -s, s, c) * d; e.y /= max(vShape.x, 0.18);
        float r = length(e); if (r > 1.0 && dot(d, d) > 1.0) discard;
        float disc = exp(-r * 5.0) * (1.0 - smoothstep(0.8, 1.0, r)), bulge = exp(-dot(d, d) / (2.0 * vSig * vSig));
        vec3 col = vCol * disc * (1.0 - vShape.z) + vec3(1.0, 0.86, 0.66) * bulge * (0.35 + vShape.z);
        gl_FragColor = vec4(col * vA * 1.4, 1.0); }` : SPRITE_FS,
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
  });
  const pts = new THREE.Points(geo, mat); pts.frustumCulled = false; pts.renderOrder = order;
  g.add(pts); universe.add(g);
  return { group: g, points: pts, U, unitKm };
}

/* ---------- the galaxies of the observable universe, one speck each (illustrative positions) ----------
   ~450,000 points strewn through the observable sphere along the same web as the volume (the real sky holds an
   estimated few hundred billion to two trillion galaxies; each speck here stands for millions of them). Farther ones
   are dimmer and redder, as the light of distant galaxies is. Inside ~1.3 billion ly the real 2MRS galaxies take over. */
const GAL_FIELD = (() => {
  const data = webTex.image.data, N = WEB_N, P = WEB_PERIOD_MPC, R = 14250, RIN = 400;     // Mpc: the observable radius; the 2MRS region
  // draw voxels of the web texture in proportion to their density (a cumulative table), then drop each into a random
  // period tile inside the sphere: the same web, without wasting draws on empty space
  const cdf = new Float64Array(N * N * N); let acc = 0;
  for (let i = 0; i < cdf.length; i++) { acc += Math.pow(data[i] / 255, 1.4); cdf[i] = acc; }
  const tex = (x, y, z) => data[((Math.floor(x * N) % N + N) % N) + N * (((Math.floor(y * N) % N + N) % N) + N * ((Math.floor(z * N) % N + N) % N))] / 255;
  const rnd = mulberry32(90210), COUNT = 450000;
  const pos = new Float32Array(COUNT * 3), size = new Float32Array(COUNT), bri = new Float32Array(COUNT), col = new Float32Array(COUNT * 3);
  let n = 0;
  while (n < COUNT) {
    const v = rnd() * acc; let lo = 0, hi = cdf.length - 1;
    while (lo < hi) { const m = (lo + hi) >> 1; if (cdf[m] < v) lo = m + 1; else hi = m; }
    const vx = lo % N, vy = Math.floor(lo / N) % N, vz = Math.floor(lo / (N * N));
    // a random tile of the periodic web inside the sphere
    const u = Math.cbrt(rnd()) * R, cz = 2 * rnd() - 1, ph = 2 * Math.PI * rnd(), sz = Math.sqrt(1 - cz * cz);
    const ox = Math.floor(u * sz * Math.cos(ph) / P) * P, oy = Math.floor(u * sz * Math.sin(ph) / P) * P, oz = Math.floor(u * cz / P) * P;
    const x = ox + (vx + rnd()) / N * P, y = oy + (vy + rnd()) / N * P, z = oz + (vz + rnd()) / N * P;
    const r = Math.hypot(x, y, z);
    if (r < RIN || r > R) continue;
    // the second, rotated layer of the shader's web modulates it (as in webDensity())
    const rx = 0.8 * x - 0.6 * y, ry = 0.36 * x + 0.48 * y + 0.8 * z, rz = -0.48 * x - 0.64 * y + 0.6 * z;
    if (rnd() * 1.65 > 0.35 + 1.3 * tex(rx / (P * 1.37) + 0.31, ry / (P * 1.37) + 0.31, rz / (P * 1.37) + 0.31)) continue;
    pos[n * 3] = x; pos[n * 3 + 1] = y; pos[n * 3 + 2] = z;
    size[n] = 0.02 + 0.03 * rnd();
    const far = Math.min(1, r / R), red = 0.85 * far * far * far;
    const kind = rnd() < 0.6 ? [0.72, 0.82, 1.0] : [1.0, 0.86, 0.62];                     // blue spirals, golden ellipticals
    col[n * 3] = kind[0] * (1 - red) + 1.0 * red; col[n * 3 + 1] = kind[1] * (1 - red) + 0.5 * red; col[n * 3 + 2] = kind[2] * (1 - red) + 0.32 * red;
    bri[n] = (0.06 + 1.5 * Math.pow(rnd(), 4)) * (1 - 0.55 * far);                             // mostly faint, a few bright (as in a deep field)
    n++;
  }
  const c = makeCloud({ positions: pos, sizes: size, brights: bri, colors: col, unitKm: KM.MPC, minPx: 0.9, maxPx: 3, gain: 0, order: 3, shape: 'soft' });
  c.U.uFade.value = 0; c.points.visible = false;
  return c;
})();
